import type { Quote } from "./quotes";

// Additional curated passages, all from public-domain translations:
// - Marcus Aurelius, Meditations — George Long (1862)
// - Epictetus, Enchiridion — Thomas Higginson (1865); Discourses — George Long (1877)
// - Seneca, Letters to Lucilius — Richard Gummere (Loeb, 1917–25)
// - Seneca, essays — John W. Basore (Loeb, 1928–35) and Aubrey Stewart (1900)
// - Musonius Rufus — Cora Lutz translations, per "Musonius Rufus: The Roman Socrates" (1947)
// IDs are stable; append-only. Do not renumber.

export const EXTRA_QUOTES: Quote[] = [
  // ============================================================
  // Marcus Aurelius — Meditations (Long translation, public domain)
  // ============================================================
  { id: "ma-1-5", text: "From my tutor I learned endurance of labour, and to want little, and to work with my own hands, and not to meddle with other people's affairs, and not to be ready to listen to slander.", author: "Marcus Aurelius", work: "Meditations", section: "1.5", translator: "George Long", themes: ["virtue","character","others"] },
  { id: "ma-1-8", text: "From Apollonius I learned freedom of will and undeviating steadiness of purpose; and to look to nothing else, not even for a moment, except to reason.", author: "Marcus Aurelius", work: "Meditations", section: "1.8", translator: "George Long", themes: ["virtue","character","control"] },
  { id: "ma-1-9", text: "From Sextus, a benevolent disposition, and the example of a family governed in a fatherly manner, and the idea of living conformably to nature; and gravity without affectation.", author: "Marcus Aurelius", work: "Meditations", section: "1.9", translator: "George Long", themes: ["virtue","character","nature"] },
  { id: "ma-1-16", text: "In my father I observed mildness of temper, and unchangeable resolution in the things which he had determined after due deliberation... a man ready to listen to those who had anything to propose for the common weal.", author: "Marcus Aurelius", work: "Meditations", section: "1.16", translator: "George Long", themes: ["virtue","character","power"] },
  { id: "ma-2-2", text: "Whatever this is that I am, it is a little flesh and breath, and the ruling part. Throw away thy books; no longer distract thyself: it is not allowed.", author: "Marcus Aurelius", work: "Meditations", section: "2.2", translator: "George Long", themes: ["death","inner-life","philosophy"] },
  { id: "ma-2-4", text: "Remember how long thou hast been putting off these things, and how often thou hast received an opportunity from the gods, and yet dost not use it.", author: "Marcus Aurelius", work: "Meditations", section: "2.4", translator: "George Long", themes: ["time","action","virtue"] },
  { id: "ma-2-5", text: "Every moment think steadily as a Roman and a man to do what thou hast in hand with perfect and simple dignity, and feeling of affection, and freedom, and justice.", author: "Marcus Aurelius", work: "Meditations", section: "2.5", translator: "George Long", themes: ["duty","virtue","action"] },
  { id: "ma-2-9", text: "This thou must always bear in mind, what is the nature of the whole, and what is my nature, and how this is related to that, and what kind of a part it is of what kind of a whole.", author: "Marcus Aurelius", work: "Meditations", section: "2.9", translator: "George Long", themes: ["nature","fate","perception"] },
  { id: "ma-2-13", text: "Nothing is more wretched than a man who traverses everything in a round, and pries into the things beneath the earth, and conjectures what is in the minds of his neighbours, without perceiving that it is sufficient to attend to the daemon within him.", author: "Marcus Aurelius", work: "Meditations", section: "2.13", translator: "George Long", themes: ["inner-life","others","virtue"] },
  { id: "ma-2-16", text: "The soul of man does violence to itself, first of all, when it becomes an abscess, and, as it were, a tumour on the universe... Secondly, when it is averse from any man, or even moves towards him with the intention of injuring, such as are the souls of those who are angry.", author: "Marcus Aurelius", work: "Meditations", section: "2.16", translator: "George Long", themes: ["anger","virtue","others"] },
  { id: "ma-3-2", text: "We ought to observe also that even the things which follow after the things which are produced according to nature contain something pleasing and attractive.", author: "Marcus Aurelius", work: "Meditations", section: "3.2", translator: "George Long", themes: ["nature","perception","contentment"] },
  { id: "ma-3-6", text: "If thou findest in human life anything better than justice, truth, temperance, fortitude... turn to it with all thy soul.", author: "Marcus Aurelius", work: "Meditations", section: "3.6", translator: "George Long", themes: ["virtue","character"] },
  { id: "ma-3-11", text: "To the aids which have been mentioned let this one still be added: make for thyself a definition or description of the thing which is presented to thee, so as to see distinctly what kind of a thing it is in its substance.", author: "Marcus Aurelius", work: "Meditations", section: "3.11", translator: "George Long", themes: ["perception","virtue"] },
  { id: "ma-3-12", text: "If thou workest at that which is before thee, following right reason seriously, vigorously, calmly, without allowing anything else to distract thee... thou wilt live happy.", author: "Marcus Aurelius", work: "Meditations", section: "3.12", translator: "George Long", themes: ["action","virtue","contentment"] },
  { id: "ma-4-2", text: "Let no act be done without a purpose, nor otherwise than according to the perfect principles of art.", author: "Marcus Aurelius", work: "Meditations", section: "4.2", translator: "George Long", themes: ["action","virtue"] },
  { id: "ma-4-8", text: "That which does not make a man worse than he was, also does not make his life worse, nor does it harm him either from without or from within.", author: "Marcus Aurelius", work: "Meditations", section: "4.8", translator: "George Long", themes: ["virtue","control","adversity"] },
  { id: "ma-4-18", text: "How much trouble he avoids who does not look to see what his neighbour says or does or thinks, but only to what he does himself, that it may be just and pure.", author: "Marcus Aurelius", work: "Meditations", section: "4.18", translator: "George Long", themes: ["others","virtue","tranquility"] },
  { id: "ma-4-19", text: "He who has a vehement desire for posthumous fame does not consider that every one of those who remember him will himself also die very soon.", author: "Marcus Aurelius", work: "Meditations", section: "4.19", translator: "George Long", themes: ["death","desire","time"] },
  { id: "ma-4-26", text: "Hast thou reason? I have. Why then dost not thou use it?", author: "Marcus Aurelius", work: "Meditations", section: "4.13", translator: "George Long", themes: ["virtue","action"] },
  { id: "ma-4-32", text: "Consider, for example, the times of Vespasian. Thou wilt see all these things: people marrying, bringing up children, sick, dying, warring, feasting, trafficking... And now that life of theirs is no where.", author: "Marcus Aurelius", work: "Meditations", section: "4.32", translator: "George Long", themes: ["death","time"] },
  { id: "ma-4-48", text: "Think continually how many physicians are dead after often contracting their eyebrows over the sick; and how many astrologers after predicting with great pretensions the deaths of others.", author: "Marcus Aurelius", work: "Meditations", section: "4.48", translator: "George Long", themes: ["death","time"] },
  { id: "ma-5-6", text: "One kind of man, when he has done a service to another, is ready to set down the favour to his account. Another is not ready to do this, but still in his own mind he thinks of the man as his debtor... But a third in a manner does not even know what he has done, but he is like a vine which has produced grapes.", author: "Marcus Aurelius", work: "Meditations", section: "5.6", translator: "George Long", themes: ["others","virtue"] },
  { id: "ma-5-8", text: "Whatever may happen to thee, it was prepared for thee from all eternity; and the implication of causes was from eternity spinning the thread of thy being.", author: "Marcus Aurelius", work: "Meditations", section: "5.8", translator: "George Long", themes: ["fate","adversity"] },
  { id: "ma-5-9", text: "Be not disgusted, nor discouraged, nor dissatisfied, if thou dost not succeed in doing everything according to right principles; but when thou hast failed, return back again.", author: "Marcus Aurelius", work: "Meditations", section: "5.9", translator: "George Long", themes: ["virtue","adversity","action"] },
  { id: "ma-5-18", text: "Nothing happens to any man which he is not formed by nature to bear.", author: "Marcus Aurelius", work: "Meditations", section: "5.18", translator: "George Long", themes: ["adversity","nature","virtue"] },
  { id: "ma-5-23", text: "Often think of the rapidity with which things pass by and disappear... For substance is like a river in a continual flow, and the activities of things are in constant change.", author: "Marcus Aurelius", work: "Meditations", section: "5.23", translator: "George Long", themes: ["time","present","nature"] },
  { id: "ma-6-2", text: "Let it make no difference to thee whether thou art cold or warm, if thou art doing thy duty; and whether thou art drowsy or satisfied with sleep... For the activity about which thou art busied is a kind of sacred function.", author: "Marcus Aurelius", work: "Meditations", section: "6.2", translator: "George Long", themes: ["duty","virtue","action"] },
  { id: "ma-6-7", text: "Take pleasure in one thing and rest in it, in passing from one social act to another social act, thinking of God.", author: "Marcus Aurelius", work: "Meditations", section: "6.7", translator: "George Long", themes: ["others","virtue","contentment"] },
  { id: "ma-6-16", text: "What then is that which ought to be valued? To be received with clapping of hands? No. Neither must we value the clapping of tongues, for the praise which comes from the many is a clapping of tongues.", author: "Marcus Aurelius", work: "Meditations", section: "6.16", translator: "George Long", themes: ["others","virtue","desire"] },
  { id: "ma-6-19", text: "If a thing is difficult to be accomplished by thyself, do not think that it is impossible for man: but if anything is possible for man and conformable to his nature, think that this can be attained by thyself too.", author: "Marcus Aurelius", work: "Meditations", section: "6.19", translator: "George Long", themes: ["virtue","action","adversity"] },
  { id: "ma-6-48", text: "When thou wishest to delight thyself, think of the virtues of those who live with thee; for instance, the activity of one, and the modesty of another, and the liberality of a third.", author: "Marcus Aurelius", work: "Meditations", section: "6.48", translator: "George Long", themes: ["others","virtue","contentment"] },
  { id: "ma-6-53", text: "Accustom thyself to attend carefully to what is said by another, and as much as it is possible, be in the speaker's mind.", author: "Marcus Aurelius", work: "Meditations", section: "6.53", translator: "George Long", themes: ["others","virtue"] },
  { id: "ma-7-3", text: "Vain pomp, plays on the stage, flocks of sheep, herds of oxen, mock combats, bones thrown to little dogs, crumbs into fish-ponds, labourings of ants and burden-carryings, runnings about of frightened little mice, puppets pulled by strings — all these are alike.", author: "Marcus Aurelius", work: "Meditations", section: "7.3", translator: "George Long", themes: ["desire","perception"] },
  { id: "ma-7-9", text: "All things are implicated with one another, and the bond is holy... For there is one common world made up of all things, and one God who pervades all things.", author: "Marcus Aurelius", work: "Meditations", section: "7.9", translator: "George Long", themes: ["nature","fate","others"] },
  { id: "ma-7-26", text: "When a man has done thee any wrong, immediately consider with what opinion about good or evil he has done wrong. For when thou hast seen this, thou wilt pity him, and wilt neither wonder nor be angry.", author: "Marcus Aurelius", work: "Meditations", section: "7.26", translator: "George Long", themes: ["anger","others","perception"] },
  { id: "ma-7-27", text: "Think not so much of what thou hast not as of what thou hast: but of the things which thou hast select the best, and then reflect how eagerly they would have been sought if thou hadst them not.", author: "Marcus Aurelius", work: "Meditations", section: "7.27", translator: "George Long", themes: ["contentment","desire","gratitude"] },
  { id: "ma-7-29", text: "Wipe out the imagination. Stop the pulling of the strings. Confine thyself to the present. Understand well what happens either to thee or to another.", author: "Marcus Aurelius", work: "Meditations", section: "7.29", translator: "George Long", themes: ["present","control","perception"] },
  { id: "ma-7-59", text: "Look within. Within is the fountain of good, and it will ever bubble up, if thou wilt ever dig.", author: "Marcus Aurelius", work: "Meditations", section: "7.59", translator: "George Long", themes: ["inner-life","virtue"] },
  { id: "ma-7-69", text: "This is the mark of perfection of character — to pass through every day as if it were the last, without agitation, without torpor, without pretence.", author: "Marcus Aurelius", work: "Meditations", section: "7.69", translator: "George Long", themes: ["death","virtue","character"] },
  { id: "ma-8-5", text: "First, do nothing inconsiderately, nor without a purpose. Second, make thy acts refer to nothing else than to a social end.", author: "Marcus Aurelius", work: "Meditations", section: "8.5", translator: "George Long", themes: ["action","virtue","others"] },
  { id: "ma-8-8", text: "It is not fit that I should give myself pain, for I have never intentionally given pain even to another.", author: "Marcus Aurelius", work: "Meditations", section: "8.8", translator: "George Long", themes: ["virtue","inner-life"] },
  { id: "ma-8-32", text: "Thou must arrange thy life, action by action, and if each action, so far as it is possible, does its office, be satisfied.", author: "Marcus Aurelius", work: "Meditations", section: "8.32", translator: "George Long", themes: ["action","virtue","contentment"] },
  { id: "ma-8-46", text: "Nothing happens to any thing which that thing is not made by nature to bear.", author: "Marcus Aurelius", work: "Meditations", section: "8.46", translator: "George Long", themes: ["adversity","nature","fate"] },
  { id: "ma-8-49", text: "Say nothing more to thyself than what the first appearances report. Suppose that it has been reported to thee that a certain person speaks ill of thee. This has been reported; but that thou hast been injured, that has not been reported.", author: "Marcus Aurelius", work: "Meditations", section: "8.49", translator: "George Long", themes: ["perception","anger","control"] },
  { id: "ma-8-59", text: "Men exist for the sake of one another. Teach them then or bear with them.", author: "Marcus Aurelius", work: "Meditations", section: "8.59", translator: "George Long", themes: ["others","virtue","anger"] },
  { id: "ma-9-3", text: "Do not despise death, but be well content with it, since this too is one of those things which nature wills.", author: "Marcus Aurelius", work: "Meditations", section: "9.3", translator: "George Long", themes: ["death","nature","fate"] },
  { id: "ma-9-4", text: "He who does wrong does wrong against himself. He who acts unjustly acts unjustly to himself, because he makes himself bad.", author: "Marcus Aurelius", work: "Meditations", section: "9.4", translator: "George Long", themes: ["virtue","character"] },
  { id: "ma-9-5", text: "He who does not do the things which he ought to do, is guilty of injustice equally with him who does the things which he ought not to do.", author: "Marcus Aurelius", work: "Meditations", section: "9.5", translator: "George Long", themes: ["duty","virtue","action"] },
  { id: "ma-9-11", text: "Love the art, poor as it may be, which thou hast learned, and be content with it; and pass through the rest of life like one who has intrusted to the gods with his whole soul all that he has.", author: "Marcus Aurelius", work: "Meditations", section: "9.29", translator: "George Long", themes: ["contentment","virtue","fate"] },
  { id: "ma-9-27", text: "When thou art offended at any man's fault, forthwith turn to thyself and reflect in what like manner thou dost err thyself.", author: "Marcus Aurelius", work: "Meditations", section: "9.27", translator: "George Long", themes: ["anger","others","inner-life"] },
  { id: "ma-9-40", text: "Either the gods have no power or they have power. If, then, they have no power, why dost thou pray to them? But if they have power, why dost thou not pray for them to give thee the faculty of not fearing any of the things which thou fearest?", author: "Marcus Aurelius", work: "Meditations", section: "9.40", translator: "George Long", themes: ["fear","fate","control"] },
  { id: "ma-10-3", text: "Everything which happens either happens in such wise as thou art formed by nature to bear it, or as thou art not formed by nature to bear it. If, then, it happens to thee in such way as thou art formed by nature to bear it, do not complain, but bear it as thou art formed by nature to bear it.", author: "Marcus Aurelius", work: "Meditations", section: "10.3", translator: "George Long", themes: ["adversity","nature","fate"] },
  { id: "ma-10-8", text: "Adorn thyself with simplicity and with indifference towards the things which lie between virtue and vice. Love mankind. Follow God.", author: "Marcus Aurelius", work: "Meditations", section: "10.8", translator: "George Long", themes: ["virtue","others","fate"] },
  { id: "ma-10-11", text: "Acquire the contemplative way of seeing how all things change into one another, and constantly attend to it, and exercise thyself about this part of philosophy. For nothing is so much adapted to produce magnanimity.", author: "Marcus Aurelius", work: "Meditations", section: "10.11", translator: "George Long", themes: ["philosophy","perception","virtue"] },
  { id: "ma-10-22", text: "It is enough to remember that the limit which is best for each thing is that which contains it; and it is not the man who chooses it, but the nature of the whole.", author: "Marcus Aurelius", work: "Meditations", section: "10.22", translator: "George Long", themes: ["nature","fate","virtue"] },
  { id: "ma-11-1", text: "These are the properties of the rational soul: it sees itself, analyses itself, and makes itself such as it chooses; the fruit which it bears itself enjoys.", author: "Marcus Aurelius", work: "Meditations", section: "11.1", translator: "George Long", themes: ["inner-life","virtue","character"] },
  { id: "ma-11-3", text: "What a soul that is which is ready, if at any moment it must be separated from the body... But this readiness must come from a man's own judgement, not from mere obstinacy, as with the Christians, but considerately and with dignity.", author: "Marcus Aurelius", work: "Meditations", section: "11.3", translator: "George Long", themes: ["death","virtue","courage"] },
  { id: "ma-11-16", text: "It is in our power to have no opinion about a thing, and not to be disturbed in our soul; for things themselves have no natural power to form our judgements.", author: "Marcus Aurelius", work: "Meditations", section: "11.16", translator: "George Long", themes: ["control","perception","tranquility"] },
  { id: "ma-12-4", text: "I have often wondered how it is that every man loves himself more than all the rest of men, but yet sets less value on his own opinion of himself than on the opinion of others.", author: "Marcus Aurelius", work: "Meditations", section: "12.4", translator: "George Long", themes: ["others","virtue","desire"] },
  { id: "ma-12-14", text: "Either there is a fatal necessity and invincible order, or a kind Providence, or a confusion without a purpose. If then there is an invincible necessity, why dost thou resist?", author: "Marcus Aurelius", work: "Meditations", section: "12.14", translator: "George Long", themes: ["fate","virtue"] },
  { id: "ma-12-27", text: "Continually think of those who have been very indignant at anything... Where are they all now? Smoke and ash, a tale, or not even a tale.", author: "Marcus Aurelius", work: "Meditations", section: "12.27", translator: "George Long", themes: ["anger","death","time"] },
  { id: "ma-12-32", text: "How small a part of boundless and unfathomable time is assigned to every man! For it is very soon swallowed up in the eternal. And how small a part of the whole substance!", author: "Marcus Aurelius", work: "Meditations", section: "12.32", translator: "George Long", themes: ["time","death","nature"] },
  { id: "ma-12-36", text: "Thou hast embarked, thou hast made the voyage, thou art come to shore; get out. If indeed to another life, there is no want of gods, not even there. But if to a state without sensation, thou wilt cease to be held by pains and pleasures.", author: "Marcus Aurelius", work: "Meditations", section: "12.36", translator: "George Long", themes: ["death","virtue","fate"] },

  // ============================================================
  // Epictetus — Enchiridion (Higginson) — remaining chapters
  // ============================================================
  { id: "ep-en-4", text: "When you are going about any action, remind yourself what nature the action is. If you are going to bathe, picture to yourself the things which usually happen in the bath: some people splash the water, some push, some use abusive language, and others steal.", author: "Epictetus", work: "Enchiridion", section: "4", translator: "Thomas Higginson", themes: ["preparation","adversity","perception"] },
  { id: "ep-en-6", text: "Don't be prideful with any excellence that is not your own. If a horse should be prideful and say, 'I am handsome,' it would be supportable. But when you are prideful, and say, 'I have a handsome horse,' know that you are proud of what is, in fact, only the good of the horse.", author: "Epictetus", work: "Enchiridion", section: "6", translator: "Thomas Higginson", themes: ["virtue","desire","character"] },
  { id: "ep-en-9", text: "Sickness is an impediment to the body, but not to the will, unless itself pleases. Lameness is an impediment to the leg, but not to the will; and say this to yourself with regard to everything that happens.", author: "Epictetus", work: "Enchiridion", section: "9", translator: "Thomas Higginson", themes: ["adversity","control","virtue"] },
  { id: "ep-en-12", text: "If you would improve, lay aside such reasonings as these: 'If I neglect my affairs, I shall not have a maintenance; if I do not punish my servant, he will be good for nothing.' For it is better to die with hunger, exempt from grief and fear, than to live in affluence with perturbation.", author: "Epictetus", work: "Enchiridion", section: "12", translator: "Thomas Higginson", themes: ["fear","virtue","desire"] },
  { id: "ep-en-14", text: "If you wish your children, and your wife, and your friends to live for ever, you are stupid; for you wish to be in control of things which you cannot, you wish for things that belong to others to be your own.", author: "Epictetus", work: "Enchiridion", section: "14", translator: "Thomas Higginson", themes: ["control","loss","desire"] },
  { id: "ep-en-18", text: "When a raven happens to croak unluckily, don't allow the appearance hurry you away with it, but immediately make the distinction to yourself, and say, 'None of these things are portended to me... to me nothing can be portended, either dangerous or unfortunate, since whatever befalls me is up to me.'", author: "Epictetus", work: "Enchiridion", section: "18", translator: "Thomas Higginson", themes: ["fear","perception","control"] },
  { id: "ep-en-19", text: "You can be unconquerable, if you enter into no combat in which it is not in your own control to conquer.", author: "Epictetus", work: "Enchiridion", section: "19", translator: "Thomas Higginson", themes: ["control","virtue","courage"] },
  { id: "ep-en-21", text: "Let death and exile, and all other things which appear terrible, be daily before your eyes, but chiefly death; and you will never entertain any abject thought, nor too eagerly covet anything.", author: "Epictetus", work: "Enchiridion", section: "21", translator: "Thomas Higginson", themes: ["death","fear","desire"] },
  { id: "ep-en-23", text: "If you have an earnest desire towards philosophy, prepare yourself from the very first to be laughed at, to be sneered by the multitude, to hear them say, 'He is returned to us a philosopher all at once.'", author: "Epictetus", work: "Enchiridion", section: "22", translator: "Thomas Higginson", themes: ["philosophy","others","virtue"] },
  { id: "ep-en-24", text: "Let not such considerations as these distress you: 'I will live in dishonour, and be nobody anywhere.' For if dishonour be an evil, you can no more be involved in any evil by means of another, than be engaged in anything base.", author: "Epictetus", work: "Enchiridion", section: "24", translator: "Thomas Higginson", themes: ["others","virtue","character"] },
  { id: "ep-en-25", text: "Has anyone been honoured above you at an entertainment, or in being saluted, or in being invited to a consultation? If these things are good, you ought to rejoice that he has got them; and if they are evil, don't be grieved that you have not got them.", author: "Epictetus", work: "Enchiridion", section: "25", translator: "Thomas Higginson", themes: ["desire","others","virtue"] },
  { id: "ep-en-27", text: "As a mark is not set up for the sake of missing the aim, so neither does the nature of evil exist in the world.", author: "Epictetus", work: "Enchiridion", section: "27", translator: "Thomas Higginson", themes: ["virtue","nature","perception"] },
  { id: "ep-en-28", text: "If a person had delivered up your body to some passer-by, you would certainly be angry. And do you feel no shame in delivering up your own mind to any reviler, to be disconcerted and confounded?", author: "Epictetus", work: "Enchiridion", section: "28", translator: "Thomas Higginson", themes: ["anger","control","inner-life"] },
  { id: "ep-en-30", text: "Duties are universally measured by relations. Is anyone a father? If so, it is implied that the children should take care of him, submit to him in everything, patiently listen to his reproaches, his correction.", author: "Epictetus", work: "Enchiridion", section: "30", translator: "Thomas Higginson", themes: ["duty","others","virtue"] },
  { id: "ep-en-32", text: "When you have recourse to divination, remember that you know not what the event will be, and you come to learn it of the diviner; but of what nature it is you knew before coming, at least if you are a philosopher.", author: "Epictetus", work: "Enchiridion", section: "32", translator: "Thomas Higginson", themes: ["fate","virtue","fear"] },
  { id: "ep-en-34", text: "If you are struck by the appearance of any promised pleasure, guard yourself against being hurried away by it; but let the affair wait your leisure, and procure yourself some delay.", author: "Epictetus", work: "Enchiridion", section: "34", translator: "Thomas Higginson", themes: ["desire","control","virtue"] },
  { id: "ep-en-35", text: "When you do anything from a clear judgement that it ought to be done, never shun the being seen to do it, even though the world should make a wrong supposition about it; for if you don't act right, shun the action itself; but, if you do, why are you afraid of those who censure you wrongly?", author: "Epictetus", work: "Enchiridion", section: "35", translator: "Thomas Higginson", themes: ["virtue","others","action"] },
  { id: "ep-en-37", text: "If you have assumed any character above your strength, you have both made an ill figure in that and quitted one which you might have supported.", author: "Epictetus", work: "Enchiridion", section: "37", translator: "Thomas Higginson", themes: ["virtue","character","action"] },
  { id: "ep-en-38", text: "In walking, you are careful not to step on a nail, or to sprain your ankle. In the same way you should be careful not to hurt the ruling faculty of your mind. And, if we were to guard against this in every action, we should undertake the action with the greater safety.", author: "Epictetus", work: "Enchiridion", section: "38", translator: "Thomas Higginson", themes: ["inner-life","virtue","action"] },
  { id: "ep-en-40", text: "Women from fourteen years old are flattered with the title of 'mistresses' by the men. Therefore, perceiving that they are regarded only as qualified to give the men pleasure, they begin to adorn themselves, and in that to place all their hopes. It is worthwhile, therefore, to fix our attention on making them sensible that they are valued for the appearance of decent, modest and discreet behaviour.", author: "Epictetus", work: "Enchiridion", section: "40", translator: "Thomas Higginson", themes: ["others","virtue","character"] },
  { id: "ep-en-42", text: "When any person harms you, or speaks badly of you, remember that he acts or speaks from a supposition of its being his duty. Now, it is not possible that he should follow what appears right to you, but what appears so to himself.", author: "Epictetus", work: "Enchiridion", section: "42", translator: "Thomas Higginson", themes: ["anger","others","perception"] },
  { id: "ep-en-44", text: "These reasonings are unconnected: 'I am richer than you, therefore I am better'; 'I am more eloquent than you, therefore I am better.' The connection is rather this: 'I am richer than you, therefore my property is greater than yours.'", author: "Epictetus", work: "Enchiridion", section: "44", translator: "Thomas Higginson", themes: ["wealth","virtue","others"] },
  { id: "ep-en-47", text: "When you have brought yourself to supply the wants of your body at a small price, don't pique yourself upon it, nor, if you drink water, be saying upon every occasion, 'I drink water.'", author: "Epictetus", work: "Enchiridion", section: "47", translator: "Thomas Higginson", themes: ["virtue","desire","character"] },
  { id: "ep-en-49", text: "When any person acts well in relation to himself, praise him not as a philosopher, but as a good man.", author: "Epictetus", work: "Enchiridion", section: "49", translator: "Thomas Higginson", themes: ["virtue","action","philosophy"] },
  { id: "ep-en-50", text: "Whatever rules you have adopted, abide by them as laws, and as if you would be impious to transgress them; and do not regard what any one says of you, for this is not your concern.", author: "Epictetus", work: "Enchiridion", section: "50", translator: "Thomas Higginson", themes: ["virtue","character","others"] },
  { id: "ep-en-52", text: "The first and most necessary topic in philosophy is the practical application of principles, as, 'We ought not to lie'; the second is that of demonstrations, as, 'Why it is that we ought not to lie'; the third, that which gives strength and articulation to the other two.", author: "Epictetus", work: "Enchiridion", section: "52", translator: "Thomas Higginson", themes: ["philosophy","virtue","action"] },
  { id: "ep-en-53", text: "Upon all occasions we ought to have these maxims ready at hand: 'Conduct me, Jove, and you, O Destiny, wherever your decrees have fixed my station. I follow cheerfully; and, did I not, wicked and wretched, I must follow still.'", author: "Epictetus", work: "Enchiridion", section: "53", translator: "Thomas Higginson", themes: ["fate","virtue","control"] },

  // Epictetus — Discourses (Long) — additional passages
  { id: "ep-dis-1-1b", text: "Some things depend on ourselves, and other things do not depend on ourselves. The things which are in our own power are conception, movement, desire, aversion.", author: "Epictetus", work: "Discourses", section: "I.1", translator: "George Long", themes: ["control","dichotomy-of-control"] },
  { id: "ep-dis-1-2", text: "Consider at what price you sell your own will: if for no other reason, that you may not sell it for a small sum.", author: "Epictetus", work: "Discourses", section: "I.2", translator: "George Long", themes: ["virtue","character","control"] },
  { id: "ep-dis-1-4", text: "Do you not know that a fine cock does not exist in isolation, but must have some pain, must fight, must be wounded? So it is with a man of virtue.", author: "Epictetus", work: "Discourses", section: "I.4", translator: "George Long", themes: ["adversity","virtue","courage"] },
  { id: "ep-dis-1-6", text: "God has introduced man to be a spectator of himself and of his works, and not only a spectator, but also an interpreter of them.", author: "Epictetus", work: "Discourses", section: "I.6", translator: "George Long", themes: ["nature","virtue","philosophy"] },
  { id: "ep-dis-1-9", text: "You are a citizen of the world, and a part of it, not one of the subservient, but one of the principal parts. You are capable of comprehending the divine administration, and of considering the connection of things.", author: "Epictetus", work: "Discourses", section: "I.9", translator: "George Long", themes: ["others","virtue","fate"] },
  { id: "ep-dis-1-12", text: "For this is a general rule: whatever we take pains to secure, that we naturally love. Does anyone take pains about things bad? By no means.", author: "Epictetus", work: "Discourses", section: "I.12", translator: "George Long", themes: ["virtue","action"] },
  { id: "ep-dis-1-16", text: "If we had understanding, ought we to do anything else, both jointly and severally, than to sing hymns and bless the deity, and tell of his benefits?", author: "Epictetus", work: "Discourses", section: "I.16", translator: "George Long", themes: ["gratitude","virtue","fate"] },
  { id: "ep-dis-1-18", text: "For to fall into error unwillingly is a man's misfortune. He who suffers pain, then, is not the sufferer of the injury, but the doer of it.", author: "Epictetus", work: "Discourses", section: "I.18", translator: "George Long", themes: ["anger","others","virtue"] },
  { id: "ep-dis-1-19", text: "Every animal is so constituted that it flees from and turns from the things that appear harmful and the things that cause the harm.", author: "Epictetus", work: "Discourses", section: "I.19", translator: "George Long", themes: ["fear","nature","perception"] },
  { id: "ep-dis-1-24", text: "'Difficulties are what show men's characters.' Therefore, when a difficulty falls upon you, remember that God, like a trainer of wrestlers, has matched you with a rough young man.", author: "Epictetus", work: "Discourses", section: "I.24", translator: "George Long", themes: ["adversity","character","virtue"] },
  { id: "ep-dis-2-6", text: "When a difficulty falls upon you, remember to turn to yourself and see what faculty you have for meeting it.", author: "Epictetus", work: "Discourses", section: "II.6", translator: "George Long", themes: ["adversity","control","virtue"] },
  { id: "ep-dis-2-9", text: "Why then do we call ourselves Stoics? Why do we deceive the many? Why do we act as if we were Jews, when we are Greeks?", author: "Epictetus", work: "Discourses", section: "II.9", translator: "George Long", themes: ["virtue","philosophy","action"] },
  { id: "ep-dis-2-16", text: "Where does the good exist? — In the will. Where does evil exist? — In the will. Where does neither of them exist? — In the things which are independent of the will.", author: "Epictetus", work: "Discourses", section: "II.16", translator: "George Long", themes: ["control","virtue","dichotomy-of-control"] },
  { id: "ep-dis-2-18", text: "Every habit and faculty is maintained and increased by the corresponding actions: the habit of walking, by walking; the habit of running, by running.", author: "Epictetus", work: "Discourses", section: "II.18", translator: "George Long", themes: ["virtue","action","character"] },
  { id: "ep-dis-3-2", text: "There are three fields of study in which he who is to be good and worthy must be exercised: that of desires and aversions; that of impulses to act and not to act; that of assent.", author: "Epictetus", work: "Discourses", section: "III.2", translator: "George Long", themes: ["virtue","philosophy","action"] },
  { id: "ep-dis-3-15", text: "In every affair consider what precedes and follows, and then undertake it. Otherwise you will begin with spirit indeed, careless of the consequences, and when these are developed, you will shamefully desist.", author: "Epictetus", work: "Discourses", section: "III.15", translator: "George Long", themes: ["action","virtue","preparation"] },
  { id: "ep-dis-3-19", text: "It is the act of an ill-instructed man to blame others for his own bad condition; it is the act of one who has begun to be instructed, to lay the blame on himself; and of one whose instruction is completed, neither to blame another, nor himself.", author: "Epictetus", work: "Discourses", section: "III.19", translator: "George Long", themes: ["virtue","character","others"] },
  { id: "ep-dis-3-20", text: "Every event has two handles — by one of which it can be borne, by the other not.", author: "Epictetus", work: "Discourses", section: "III.20", translator: "George Long", themes: ["adversity","perception","control"] },
  { id: "ep-dis-3-24", text: "The universe is one, and God, who pervades all things, is one, and substance is one, and law is one, that is, the common reason of all intelligent animals, and truth is one.", author: "Epictetus", work: "Discourses", section: "III.24", translator: "George Long", themes: ["nature","fate","philosophy"] },
  { id: "ep-dis-4-4", text: "Freedom is not procured by a full enjoyment of what is desired, but by controlling the desire.", author: "Epictetus", work: "Discourses", section: "IV.1", translator: "George Long", themes: ["desire","control","virtue"] },
  { id: "ep-dis-4-6", text: "No one who is either in fear or in sorrow or in perturbation is free; but whoever is delivered from sorrows and fears and perturbations, he by the very same means is delivered also from slavery.", author: "Epictetus", work: "Discourses", section: "IV.1", translator: "George Long", themes: ["fear","control","virtue"] },
  { id: "ep-dis-4-10", text: "It is impossible for a man to learn what he thinks he already knows.", author: "Epictetus", work: "Discourses", section: "II.17", translator: "George Long", themes: ["virtue","philosophy","perception"] },
  { id: "ep-dis-frag-1", text: "Only the educated are free.", author: "Epictetus", work: "Fragments", section: "18", translator: "George Long", themes: ["virtue","philosophy","control"] },
  { id: "ep-dis-frag-2", text: "If you wish to make Pythocles rich, do not give him more money, but diminish his desires.", author: "Epictetus", work: "Fragments", section: "25", translator: "George Long", themes: ["desire","wealth","contentment"] },

  // ============================================================
  // Seneca — Letters to Lucilius (Gummere) — additional
  // ============================================================
  { id: "se-ep-6", text: "Homines, dum docent, discunt. Men learn while they teach.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 7", translator: "Richard Gummere", themes: ["others","virtue","philosophy"] },
  { id: "se-ep-8", text: "In order to make good progress, the wise man's peace should not be disturbed by any external event... But the wise man will never provoke the anger of those in power; nay, he will turn his course, precisely as he would turn from a storm.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 14", translator: "Richard Gummere", themes: ["tranquility","adversity","virtue"] },
  { id: "se-ep-10", text: "Recede in te ipsum quantum potes. Withdraw into yourself as far as you can.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 25", translator: "Richard Gummere", themes: ["inner-life","virtue"] },
  { id: "se-ep-11", text: "The primary indication, to my thinking, of a well-ordered mind is a man's ability to remain in one place and linger in his own company.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 2", translator: "Richard Gummere", themes: ["tranquility","inner-life","virtue"] },
  { id: "se-ep-15", text: "The mind must be given relaxation; it will rise improved and sharper after a good break... Return to your studies as often as you can; but you should also allow relaxation to your mind.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 15", translator: "Richard Gummere", themes: ["virtue","character","tranquility"] },
  { id: "se-ep-19", text: "A wise man is content with himself, and yet needs friends. He wishes to have as many friends as possible, not, however, that he may live happily; for he will live happily even without friends.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 9", translator: "Richard Gummere", themes: ["friendship","virtue","contentment"] },
  { id: "se-ep-21", text: "Cui cum paupertate bene convenit, dives est. Not he who has little, but he who craves more, is poor.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 2", translator: "Richard Gummere", themes: ["wealth","desire","contentment"] },
  { id: "se-ep-22", text: "It is not the man who has too little who is poor, but the one who hankers after more.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 2", translator: "Richard Gummere", themes: ["wealth","desire","contentment"] },
  { id: "se-ep-24", text: "Rehearse this thought every day, that you may be able to depart from life contentedly; for many men clutch and cling to life, even as those who are carried down a rushing stream clutch and cling to briars and sharp rocks.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 4", translator: "Richard Gummere", themes: ["death","fear","virtue"] },
  { id: "se-ep-25", text: "Recede in te ipse; sed ante te ipsum praepara ut recipiaris. Withdraw into yourself; but first prepare yourself to receive yourself.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 7", translator: "Richard Gummere", themes: ["inner-life","virtue"] },
  { id: "se-ep-27", text: "As long as you live, keep learning how to live.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 76", translator: "Richard Gummere", themes: ["virtue","philosophy","time"] },
  { id: "se-ep-31", text: "The man who has anticipated the coming of troubles takes away their power when they arrive.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 76", translator: "Richard Gummere", themes: ["fear","adversity","preparation"] },
  { id: "se-ep-33", text: "There is no glory in outstripping donkeys.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 31", translator: "Richard Gummere", themes: ["virtue","others"] },
  { id: "se-ep-37", text: "The bravest sight in the world is to see a great man struggling against adversity; yet there is a still greater sight — a great man cheerfully at grips with adversity.", author: "Seneca", work: "On Providence", section: "2.9", translator: "Aubrey Stewart", themes: ["adversity","courage","virtue"] },
  { id: "se-ep-40", text: "Trust me, it is better to understand the balance-sheet of one's own life than of the corn-trade.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 26", translator: "Richard Gummere", themes: ["inner-life","virtue","time"] },
  { id: "se-ep-45", text: "It is my great pleasure to seek out wise men, but I am not going to sail past Africa in order to hear that Metrodorus was not so miserable as he thought he was.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 45", translator: "Richard Gummere", themes: ["virtue","philosophy","desire"] },
  { id: "se-ep-49", text: "No one lives poorly who dies well, and no one lives well who dies poorly.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 61", translator: "Richard Gummere", themes: ["death","virtue","time"] },
  { id: "se-ep-53", text: "It is not because things are difficult that we do not dare; it is because we do not dare that they are difficult.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 104", translator: "Richard Gummere", themes: ["adversity","courage","virtue"] },
  { id: "se-ep-54", text: "The soul should know whither it is going and whence it came, what is good for it and what is evil, what it seeks and what it avoids, and what is that Reason which distinguishes between the desirable and the undesirable.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 88", translator: "Richard Gummere", themes: ["inner-life","virtue","philosophy"] },
  { id: "se-ep-55", text: "Non refert quam multos libros habeas, sed quam bonos. It is quality rather than quantity that matters in books.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 45", translator: "Richard Gummere", themes: ["philosophy","virtue"] },
  { id: "se-ep-56", text: "Non est ad astra mollis e terris via. There is no easy way from the earth to the stars.", author: "Seneca", work: "Hercules Furens", section: "437", translator: "F. J. Miller", themes: ["adversity","virtue"] },
  { id: "se-ep-58", text: "Nowhere is he who is everywhere.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 2", translator: "Richard Gummere", themes: ["virtue","desire","tranquility"] },
  { id: "se-ep-60", text: "The mind is never right but when it is at peace within itself.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 56", translator: "Richard Gummere", themes: ["tranquility","inner-life","virtue"] },
  { id: "se-ep-62", text: "As soon as some men become impatient of poverty, they lay hold on riches, and then find themselves in more embarrassment than ever.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 17", translator: "Richard Gummere", themes: ["wealth","desire","adversity"] },
  { id: "se-ep-63", text: "Great grief cannot be quenched; but neither can it endure forever.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 63", translator: "Richard Gummere", themes: ["grief","time","adversity"] },
  { id: "se-ep-70", text: "It is not that things are so evil, but that our judgments concerning them are so.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 78", translator: "Richard Gummere", themes: ["perception","adversity","virtue"] },
  { id: "se-ep-76", text: "So long as you live, keep learning how to live.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 76", translator: "Richard Gummere", themes: ["philosophy","virtue","time"] },
  { id: "se-ep-80", text: "Slavery resides beneath marble and gold... Riches are the greatest cause of human sorrow.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 80", translator: "Richard Gummere", themes: ["wealth","desire","virtue"] },
  { id: "se-ep-85", text: "The wise man is joyful, happy, calm, unshaken; he lives on a level with the gods.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 59", translator: "Richard Gummere", themes: ["virtue","contentment","tranquility"] },
  { id: "se-ep-90", text: "Non satis est monere, admonere debemus. It is not enough to warn — we must remind.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 94", translator: "Richard Gummere", themes: ["virtue","action","others"] },
  { id: "se-ep-96", text: "Vivere, Lucili, militare est. To live, Lucilius, is to fight.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 96", translator: "Richard Gummere", themes: ["adversity","virtue","courage"] },
  { id: "se-ep-98", text: "Non qui parum habet sed qui plus cupit pauper est. He is not poor who has little, but he who wants much.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 2", translator: "Richard Gummere", themes: ["wealth","desire","contentment"] },
  { id: "se-ep-99", text: "We should not, like sheep, follow the herd of creatures in front of us, going where they go, not where we ought to go.", author: "Seneca", work: "On the Happy Life", section: "1.3", translator: "John W. Basore", themes: ["others","virtue","character"] },
  { id: "se-ep-102", text: "A great pilot can sail even when his canvas is rent; if his ship be dismantled, he can yet put in trim what remains of her hull and hold his course.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 85", translator: "Richard Gummere", themes: ["adversity","courage","virtue"] },
  { id: "se-ep-105", text: "The whole future lies in uncertainty: live immediately.", author: "Seneca", work: "On the Shortness of Life", section: "9.1", translator: "John W. Basore", themes: ["time","present","action"] },
  { id: "se-ep-108", text: "As is a tale, so is life: not how long it is, but how good it is, is what matters.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 77", translator: "Richard Gummere", themes: ["death","virtue","time"] },
  { id: "se-ep-110", text: "No man is crushed by misfortune unless he has first been deceived by prosperity.", author: "Seneca", work: "Consolation to Helvia", section: "5.4", translator: "John W. Basore", themes: ["adversity","fate","wealth"] },
  { id: "se-ep-115", text: "Great things cannot be born of hasty efforts.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 71", translator: "Richard Gummere", themes: ["virtue","action","time"] },
  { id: "se-ep-118", text: "Ambition destroys many blessings.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 118", translator: "Richard Gummere", themes: ["desire","virtue","tranquility"] },
  { id: "se-ep-120", text: "The greatest obstacle to living is expectancy, which depends upon tomorrow and wastes today.", author: "Seneca", work: "On the Shortness of Life", section: "9.1", translator: "John W. Basore", themes: ["time","present","desire"] },
  { id: "se-ep-123", text: "No one confines his unhappiness to the present.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 5", translator: "Richard Gummere", themes: ["anxiety","present","fear"] },

  // Seneca — On Anger (Basore) — additional
  { id: "se-ang-4", text: "Anger is a short madness.", author: "Seneca", work: "On Anger", section: "I.1", translator: "John W. Basore", themes: ["anger"] },
  { id: "se-ang-5", text: "The greatest cure of anger is delay: beg anger to grant thee this at the first, not that it may pardon the offence, but that it may judge of it aright.", author: "Seneca", work: "On Anger", section: "II.29", translator: "John W. Basore", themes: ["anger","virtue","patience"] },
  { id: "se-ang-6", text: "The best remedy for injuries is to forget them.", author: "Seneca", work: "On Anger", section: "II.32", translator: "John W. Basore", themes: ["anger","others","virtue"] },
  { id: "se-ang-7", text: "It is more civilized to make fun of life than to bewail it.", author: "Seneca", work: "On Tranquility of Mind", section: "XV.2", translator: "John W. Basore", themes: ["adversity","virtue","tranquility"] },
  { id: "se-ang-8", text: "As a rule, men become angry with those things they either do not expect, or do not wish. Nothing weighs upon us more heavily than the unexpected.", author: "Seneca", work: "On Anger", section: "III.6", translator: "John W. Basore", themes: ["anger","preparation","adversity"] },

  // Seneca — On the Shortness of Life
  { id: "se-brev-2", text: "Life, if you know how to use it, is long.", author: "Seneca", work: "On the Shortness of Life", section: "2.1", translator: "John W. Basore", themes: ["time","virtue","action"] },
  { id: "se-brev-8", text: "You act like mortals in all that you fear, and like immortals in all that you desire.", author: "Seneca", work: "On the Shortness of Life", section: "3.4", translator: "John W. Basore", themes: ["desire","death","fear"] },
  { id: "se-brev-10", text: "It is inevitable that life will be, not just very short, but very miserable, for those who acquire by great toil what they must keep by greater toil.", author: "Seneca", work: "On the Shortness of Life", section: "17.4", translator: "John W. Basore", themes: ["wealth","desire","time"] },
  { id: "se-brev-14", text: "Of all people, only those are at leisure who make time for philosophy — only those are really alive. For not only do they keep a good watch over their own lifetimes, but they annex every age to theirs.", author: "Seneca", work: "On the Shortness of Life", section: "14.1", translator: "John W. Basore", themes: ["philosophy","time","virtue"] },

  // Seneca — On Providence
  { id: "se-prov-3", text: "God does not make a spoiled pet of a good man. He tests him, hardens him, and prepares him for his own service.", author: "Seneca", work: "On Providence", section: "1.6", translator: "Aubrey Stewart", themes: ["adversity","virtue","fate"] },
  { id: "se-prov-5", text: "Fire tests gold, and misery tests brave men.", author: "Seneca", work: "On Providence", section: "5.9", translator: "Aubrey Stewart", themes: ["adversity","courage","virtue"] },

  // Seneca — On Tranquility of Mind
  { id: "se-tr-1", text: "Nusquam est qui ubique est. He is nowhere who is everywhere.", author: "Seneca", work: "On Tranquility of Mind", section: "II.13", translator: "John W. Basore", themes: ["tranquility","desire","virtue"] },
  { id: "se-tr-3", text: "No man is more unhappy than he who never faces adversity. For he is not permitted to prove himself.", author: "Seneca", work: "On Providence", section: "3.3", translator: "Aubrey Stewart", themes: ["adversity","virtue","fate"] },
  { id: "se-tr-5", text: "It is quality of life, not quantity, that matters.", author: "Seneca", work: "On Tranquility of Mind", section: "III", translator: "John W. Basore", themes: ["virtue","time"] },
  { id: "se-tr-7", text: "Whatever course you take, you will fall foul of your own vices. Change of place does not diminish these; travel does not lessen them.", author: "Seneca", work: "On Tranquility of Mind", section: "II.1", translator: "John W. Basore", themes: ["inner-life","desire","virtue"] },

  // Seneca — On the Happy Life
  { id: "se-vita-3", text: "There is no delight in owning anything unshared.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 6", translator: "Richard Gummere", themes: ["friendship","others","virtue"] },
  { id: "se-vita-4", text: "The wise man will live as long as he ought, not as long as he can.", author: "Seneca", work: "Letters to Lucilius", section: "Letter 70", translator: "Richard Gummere", themes: ["death","virtue"] },

  // ============================================================
  // Musonius Rufus — Lectures (Lutz translation, widely available)
  // ============================================================
  { id: "mu-2", text: "Since a human being happens to be neither soul alone, nor body alone, but a kind of composite of the two, the person in training must take care of both.", author: "Musonius Rufus", work: "Lectures", section: "II", translator: "Cora Lutz", themes: ["virtue","character"] },
  { id: "mu-5", text: "We must use each of these two kinds of exercise, the more so the body since it is nearer at hand and more within our reach, but not to the neglect of the more important.", author: "Musonius Rufus", work: "Lectures", section: "VI", translator: "Cora Lutz", themes: ["virtue","character","action"] },
  { id: "mu-13", text: "The chief end of marriage is to live in community, and to procreate children... They must not marry for wealth or noble birth, but for character.", author: "Musonius Rufus", work: "Lectures", section: "XIII", translator: "Cora Lutz", themes: ["others","virtue","character"] },
  { id: "mu-14", text: "Even more than the artisan requires his tools, the man aiming at virtue requires philosophy.", author: "Musonius Rufus", work: "Lectures", section: "XIV", translator: "Cora Lutz", themes: ["philosophy","virtue"] },
  { id: "mu-17", text: "What good is a great deal of food when nothing wholesome is eaten? Or a great deal of wine when nothing sober is drunk? So it is with much learning when nothing sound is learned.", author: "Musonius Rufus", work: "Lectures", section: "XVII", translator: "Cora Lutz", themes: ["desire","virtue","philosophy"] },
  { id: "mu-18", text: "The purpose of taking food is not pleasure, but rather nourishment. Health is the end.", author: "Musonius Rufus", work: "Lectures", section: "XVIII", translator: "Cora Lutz", themes: ["desire","virtue","character"] },
  { id: "mu-19", text: "Clothing is for the sake of the body, not for display.", author: "Musonius Rufus", work: "Lectures", section: "XIX", translator: "Cora Lutz", themes: ["desire","virtue","character"] },
  { id: "mu-20", text: "Practice is more effective than theory, because it leads the man to action; but theory prepares the man to act.", author: "Musonius Rufus", work: "Lectures", section: "V", translator: "Cora Lutz", themes: ["virtue","action","philosophy"] },
  { id: "mu-frag-38", text: "One would gain nothing from philosophy unless he practiced the doctrines every day.", author: "Musonius Rufus", work: "Fragments", section: "38", translator: "Cora Lutz", themes: ["philosophy","virtue","action"] },
  { id: "mu-frag-40", text: "You will earn the respect of all if you begin by earning the respect of yourself.", author: "Musonius Rufus", work: "Fragments", section: "40", translator: "Cora Lutz", themes: ["virtue","character","others"] },
  { id: "mu-frag-41", text: "The person who has the greater knowledge and the greater practice will lead the more virtuous life.", author: "Musonius Rufus", work: "Fragments", section: "41", translator: "Cora Lutz", themes: ["virtue","philosophy","action"] },
];